#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairLiveSnapshotV1 {
    pub pool: [u8; 32],
    pub deployment_domain: [u8; 32],
    pub sequence: u64,
    pub next_pair_index: u64,
    pub current_root: Digest,
    pub frontier: [Digest; POOL_V1_PAIR_TREE_DEPTH],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairLatePublicStatementV1 {
    pub live_snapshot: PoolV1PairLiveSnapshotV1,
    /// One appended pair advances the pair index by one even though a private
    /// transfer fills two commitment slots (note indices `2i` and `2i+1`).
    pub candidate_afterstate: PoolV1PairVerifiedAfterstateV1,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairLatePublicStatementErrorV1 {
    WrongLength,
    WrongMagic,
    WrongVersion,
    WrongItemCount,
    WrongHeaderLength,
    WrongSnapshotLength,
    WrongAfterstateLength,
    WrongTotalLength,
    NonZeroReserved,
    Snapshot(PoolV1PairLiveSnapshotErrorV1),
    Afterstate(PoolV1PairVerifierTransportErrorV1),
    AfterstateIndexMismatch,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairLiveSnapshotErrorV1 {
    WrongLength,
    WrongMagic,
    WrongVersion,
    WrongFormatBinding,
    NonZeroReserved,
    ZeroRequiredBinding,
    SequenceIndexMismatch,
    TreeFull,
    NonCanonicalDigest,
}

fn validate_pool_v1_pair_live_snapshot_v1(
    snapshot: &PoolV1PairLiveSnapshotV1,
) -> Result<(), PoolV1PairLiveSnapshotErrorV1> {
    if snapshot.pool == [0u8; 32] || snapshot.deployment_domain == [0u8; 32] {
        return Err(PoolV1PairLiveSnapshotErrorV1::ZeroRequiredBinding);
    }
    if snapshot.sequence != snapshot.next_pair_index {
        return Err(PoolV1PairLiveSnapshotErrorV1::SequenceIndexMismatch);
    }
    if snapshot.next_pair_index >= POOL_V1_PAIR_CAPACITY {
        return Err(PoolV1PairLiveSnapshotErrorV1::TreeFull);
    }
    if !digest_is_canonical(&snapshot.current_root) {
        return Err(PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest);
    }
    let mut level = 0;
    while level < snapshot.frontier.len() {
        if !digest_is_canonical(&snapshot.frontier[level]) {
            return Err(PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest);
        }
        level += 1;
    }
    Ok(())
}

pub fn encode_pool_v1_pair_live_snapshot_v1(
    snapshot: &PoolV1PairLiveSnapshotV1,
    output: &mut [u8],
) -> Result<(), PoolV1PairLiveSnapshotErrorV1> {
    if output.len() != POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES {
        return Err(PoolV1PairLiveSnapshotErrorV1::WrongLength);
    }
    validate_pool_v1_pair_live_snapshot_v1(snapshot)?;

    output.fill(0);
    output[..8].copy_from_slice(&POOL_V1_PAIR_LIVE_SNAPSHOT_MAGIC);
    output[8] = POOL_V1_PAIR_LIVE_SNAPSHOT_VERSION;
    output[16..48].copy_from_slice(&POOL_V1_PAIR_TREE_FORMAT_BINDING);
    output[48..80].copy_from_slice(&snapshot.pool);
    output[80..112].copy_from_slice(&snapshot.deployment_domain);
    output[112..120].copy_from_slice(&snapshot.sequence.to_le_bytes());
    output[120..128].copy_from_slice(&snapshot.next_pair_index.to_le_bytes());
    output[128..160].copy_from_slice(&encode_digest_canonical(&snapshot.current_root));
    for (level, node) in snapshot.frontier.iter().enumerate() {
        let start = 160 + 32 * level;
        output[start..start + 32].copy_from_slice(&encode_digest_canonical(node));
    }
    Ok(())
}

pub fn decode_pool_v1_pair_live_snapshot_v1(
    bytes: &[u8],
) -> Result<PoolV1PairLiveSnapshotV1, PoolV1PairLiveSnapshotErrorV1> {
    if bytes.len() != POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES {
        return Err(PoolV1PairLiveSnapshotErrorV1::WrongLength);
    }
    if bytes[..8] != POOL_V1_PAIR_LIVE_SNAPSHOT_MAGIC[0..8] {
        return Err(PoolV1PairLiveSnapshotErrorV1::WrongMagic);
    }
    if bytes[8] != POOL_V1_PAIR_LIVE_SNAPSHOT_VERSION {
        return Err(PoolV1PairLiveSnapshotErrorV1::WrongVersion);
    }
    if bytes[9] != 0
        || bytes[10] != 0
        || bytes[11] != 0
        || bytes[12] != 0
        || bytes[13] != 0
        || bytes[14] != 0
        || bytes[15] != 0
    {
        return Err(PoolV1PairLiveSnapshotErrorV1::NonZeroReserved);
    }
    if bytes[16..48] != POOL_V1_PAIR_TREE_FORMAT_BINDING[0..32] {
        return Err(PoolV1PairLiveSnapshotErrorV1::WrongFormatBinding);
    }
    let current_root = decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
        bytes[128..160].try_into(),
    ))
    .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?;
    let frontier = [
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[160..192].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[192..224].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[224..256].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[256..288].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[288..320].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[320..352].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[352..384].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[384..416].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[416..448].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[448..480].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[480..512].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[512..544].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[544..576].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[576..608].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[608..640].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[640..672].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[672..704].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[704..736].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[736..768].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
        decode_digest_canonical(crate::atomic_statement::unwrap_fixed_slice(
            bytes[768..800].try_into(),
        ))
        .map_err(|_| PoolV1PairLiveSnapshotErrorV1::NonCanonicalDigest)?,
    ];
    let snapshot = PoolV1PairLiveSnapshotV1 {
        pool: crate::atomic_statement::unwrap_fixed_slice(bytes[48..80].try_into()),
        deployment_domain: crate::atomic_statement::unwrap_fixed_slice(bytes[80..112].try_into()),
        sequence: u64::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
            bytes[112..120].try_into(),
        )),
        next_pair_index: u64::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
            bytes[120..128].try_into(),
        )),
        current_root,
        frontier,
    };
    validate_pool_v1_pair_live_snapshot_v1(&snapshot)?;
    Ok(snapshot)
}

pub fn encode_pool_v1_pair_late_public_statement_v1(
    statement: &PoolV1PairLatePublicStatementV1,
    output: &mut [u8],
) -> Result<(), PoolV1PairLatePublicStatementErrorV1> {
    if output.len() != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongLength);
    }
    if statement.live_snapshot.next_pair_index.checked_add(1)
        != Some(statement.candidate_afterstate.next_pair_index)
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::AfterstateIndexMismatch);
    }
    output.fill(0);
    output[..8].copy_from_slice(&POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_MAGIC);
    output[8] = POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_VERSION;
    output[9] = POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_ITEM_COUNT;
    output[10..12]
        .copy_from_slice(&(POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_HEADER_BYTES as u16).to_le_bytes());
    output[12..16].copy_from_slice(&(POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES as u32).to_le_bytes());
    output[16..20].copy_from_slice(&(POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES as u32).to_le_bytes());
    output[20..24]
        .copy_from_slice(&(POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES as u32).to_le_bytes());
    encode_pool_v1_pair_live_snapshot_v1(
        &statement.live_snapshot,
        &mut output[32..32 + POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES],
    )
    .map_err(|error| PoolV1PairLatePublicStatementErrorV1::Snapshot(error))?;
    let encoded_afterstate =
        encode_pool_v1_pair_verified_afterstate_v1(&statement.candidate_afterstate)
            .map_err(|error| PoolV1PairLatePublicStatementErrorV1::Afterstate(error))?;
    output[32 + POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES..].copy_from_slice(&encoded_afterstate);
    Ok(())
}

#[inline(never)]
fn decode_pair_live_snapshot_boxed_v1(
    bytes: &[u8],
) -> Result<Box<PoolV1PairLiveSnapshotV1>, PoolV1PairLatePublicStatementErrorV1> {
    Ok(Box::new(
        decode_pool_v1_pair_live_snapshot_v1(bytes)
            .map_err(PoolV1PairLatePublicStatementErrorV1::Snapshot)?,
    ))
}

#[inline(never)]
fn decode_pair_afterstate_boxed_v1(
    bytes: &[u8],
) -> Result<Box<PoolV1PairVerifiedAfterstateV1>, PoolV1PairLatePublicStatementErrorV1> {
    Ok(Box::new(
        decode_pool_v1_pair_verified_afterstate_v1(bytes)
            .map_err(PoolV1PairLatePublicStatementErrorV1::Afterstate)?,
    ))
}

pub(crate) fn decode_pool_v1_pair_late_public_statement_boxed_v1(
    bytes: &[u8],
) -> Result<Box<PoolV1PairLatePublicStatementV1>, PoolV1PairLatePublicStatementErrorV1> {
    if bytes.len() != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongLength);
    }
    if bytes[..8] != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_MAGIC[0..8] {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongMagic);
    }
    if bytes[8] != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_VERSION {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongVersion);
    }
    if bytes[9] != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_ITEM_COUNT {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongItemCount);
    }
    if u16::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
        bytes[10..12].try_into(),
    )) as usize
        != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_HEADER_BYTES
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongHeaderLength);
    }
    if u32::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
        bytes[12..16].try_into(),
    )) as usize
        != POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongSnapshotLength);
    }
    if u32::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
        bytes[16..20].try_into(),
    )) as usize
        != POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongAfterstateLength);
    }
    if u32::from_le_bytes(crate::atomic_statement::unwrap_fixed_slice(
        bytes[20..24].try_into(),
    )) as usize
        != POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::WrongTotalLength);
    }
    if bytes[24] != 0
        || bytes[25] != 0
        || bytes[26] != 0
        || bytes[27] != 0
        || bytes[28] != 0
        || bytes[29] != 0
        || bytes[30] != 0
        || bytes[31] != 0
    {
        return Err(PoolV1PairLatePublicStatementErrorV1::NonZeroReserved);
    }
    let live_snapshot =
        decode_pair_live_snapshot_boxed_v1(&bytes[32..32 + POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES])?;
    let candidate_afterstate =
        decode_pair_afterstate_boxed_v1(&bytes[32 + POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES..])?;
    if live_snapshot.next_pair_index.checked_add(1) != Some(candidate_afterstate.next_pair_index) {
        return Err(PoolV1PairLatePublicStatementErrorV1::AfterstateIndexMismatch);
    }
    Ok(Box::new(PoolV1PairLatePublicStatementV1 {
        live_snapshot: *live_snapshot,
        candidate_afterstate: *candidate_afterstate,
    }))
}

pub fn decode_pool_v1_pair_late_public_statement_v1(
    bytes: &[u8],
) -> Result<PoolV1PairLatePublicStatementV1, PoolV1PairLatePublicStatementErrorV1> {
    Ok(*decode_pool_v1_pair_late_public_statement_boxed_v1(bytes)?)
}

/// Bind one complete framed statement before the C1 root and before lambda
/// and chi. No late trace commitment may be selected between this call and
/// those challenges in the merged-bank profile.
pub fn absorb_pool_v1_pair_public_statement_before_c1_root_v1(
    transcript: &mut Transcript,
    bytes: &[u8],
) -> Result<PoolV1PairLatePublicStatementV1, PoolV1PairLatePublicStatementErrorV1> {
    let statement = decode_pool_v1_pair_late_public_statement_v1(bytes)?;
    transcript.absorb_two(
        label::V7_PAIR_LIVE_APPEND_SNAPSHOT,
        POOL_V1_PAIR_PUBLIC_STATEMENT_TRANSCRIPT_DOMAIN,
        bytes,
    );
    Ok(statement)
}

#[cfg(test)]
mod tests {
    use super::*;
    use sha2::{Digest as _, Sha256};

    fn sha256(inputs: &[&[u8]]) -> [u8; 32] {
        let mut hasher = Sha256::new();
        for input in inputs {
            hasher.update(input);
        }
        hasher.finalize().into()
    }

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|lane| M31(seed + lane as u32 + 1))
    }

    #[test]
    fn empty_and_occupied_slots_are_algebraically_distinct() {
        let first = digest(10);
        let empty = PoolV1PairLeafWitnessV1::single_output(first).unwrap();
        assert_eq!(empty.validate(), Ok(()));
        assert_eq!(
            empty.require_selected_spendable(true),
            Err(PoolV1PairLeafErrorV1::SelectedSlotEmpty)
        );
        assert_eq!(
            empty.leaf_digest().unwrap(),
            pool_v1_tree_parent(&first, &[M31::ZERO; 8])
        );

        let occupied = PoolV1PairLeafWitnessV1::two_outputs(first, digest(100)).unwrap();
        assert_eq!(occupied.second_occupied, M31::ONE);
        assert_eq!(occupied.validate(), Ok(()));
        assert_eq!(occupied.require_selected_spendable(true), Ok(()));
    }

    #[test]
    fn occupied_zero_sentinel_is_a_retry_not_an_empty_hash_assumption() {
        let mut second = digest(100);
        second[POOL_V1_PAIR_SECOND_SENTINEL_LANE] = M31::ZERO;
        assert_eq!(
            PoolV1PairLeafWitnessV1::two_outputs(digest(10), second),
            Err(PoolV1PairLeafErrorV1::OccupiedSentinelZero)
        );
    }

    #[test]
    fn occupancy_cannot_be_changed_without_invalidating_the_same_pair_preimage() {
        let occupied = PoolV1PairLeafWitnessV1::two_outputs(digest(10), digest(100)).unwrap();
        let mut claimed_empty = occupied;
        claimed_empty.second_occupied = M31::ZERO;
        claimed_empty.second_occupancy_inverse = M31::ZERO;
        assert_eq!(
            claimed_empty.validate(),
            Err(PoolV1PairLeafErrorV1::EmptyCommitmentNonZero)
        );
    }

    #[test]
    fn exact_trace_boundaries_and_degree_cap_are_source_frozen() {
        assert_eq!(
            pool_v1_pair_poseidon_block_role_v1(0),
            Some(PoolV1PairPoseidonBlockRoleV1::OwnerKey)
        );
        assert_eq!(
            pool_v1_pair_poseidon_block_role_v1(33),
            Some(PoolV1PairPoseidonBlockRoleV1::OutputPair)
        );
        assert_eq!(
            pool_v1_pair_poseidon_block_role_v1(53),
            Some(PoolV1PairPoseidonBlockRoleV1::AppendTreePath(19))
        );
        assert_eq!(pool_v1_pair_poseidon_block_role_v1(54), None);
        assert_eq!(pool_v1_pair_path_base_row_v1(0), Some(865));
        assert_eq!(pool_v1_pair_path_base_row_v1(20), Some(945));
        assert_eq!(pool_v1_pair_path_base_row_v1(21), None);
        assert_eq!(POOL_V1_PAIR_SEMANTIC_ROW_END, 976);
        assert_eq!(POOL_V1_PAIR_UNALLOCATED_SEMANTIC_ROWS, 48);
        assert_eq!(POOL_V1_PAIR_MAX_DEPLOYED_DEGREE, 27);
        assert_eq!(POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW, 969);
        assert_eq!(POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW, 970);
        assert_eq!(POOL_V1_PAIR_OCCUPANCY_COMMITMENT_COLUMN_END, 10);
        assert_eq!(
            POOL_V1_PAIR_STAGED_TRANSCRIPT_PREFIX_V1[4],
            PoolV1PairTranscriptStepV1::LiveAppendSnapshot
        );
    }

    #[test]
    fn live_snapshot_encoding_is_exact_and_rejects_stale_shape() {
        let snapshot = PoolV1PairLiveSnapshotV1 {
            pool: [1u8; 32],
            deployment_domain: [2u8; 32],
            sequence: 73,
            next_pair_index: 73,
            current_root: digest(300),
            frontier: core::array::from_fn(|level| digest(400 + 10 * level as u32)),
        };
        let mut encoded = [0u8; POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES];
        encode_pool_v1_pair_live_snapshot_v1(&snapshot, &mut encoded).unwrap();
        assert_eq!(&encoded[..8], &POOL_V1_PAIR_LIVE_SNAPSHOT_MAGIC);
        assert_eq!(&encoded[16..48], &POOL_V1_PAIR_TREE_FORMAT_BINDING);
        assert_eq!(
            u64::from_le_bytes(encoded[112..120].try_into().unwrap()),
            73
        );
        assert_eq!(
            u64::from_le_bytes(encoded[120..128].try_into().unwrap()),
            73
        );
        assert_eq!(
            &encoded[768..800],
            &encode_digest_canonical(&snapshot.frontier[19])
        );
        assert_eq!(decode_pool_v1_pair_live_snapshot_v1(&encoded), Ok(snapshot));

        let mut stale = snapshot;
        stale.sequence += 1;
        assert_eq!(
            encode_pool_v1_pair_live_snapshot_v1(&stale, &mut encoded),
            Err(PoolV1PairLiveSnapshotErrorV1::SequenceIndexMismatch)
        );
    }

    fn late_statement() -> PoolV1PairLatePublicStatementV1 {
        PoolV1PairLatePublicStatementV1 {
            live_snapshot: PoolV1PairLiveSnapshotV1 {
                pool: [1u8; 32],
                deployment_domain: [2u8; 32],
                sequence: 73,
                next_pair_index: 73,
                current_root: digest(300),
                frontier: core::array::from_fn(|level| digest(400 + 10 * level as u32)),
            },
            candidate_afterstate: PoolV1PairVerifiedAfterstateV1 {
                next_pair_index: 74,
                next_root: digest(700),
                next_frontier: core::array::from_fn(|level| digest(800 + 10 * level as u32)),
            },
        }
    }

    fn merged_c1_transcript(bytes: &[u8]) -> [u8; 32] {
        let mut transcript = Transcript::new(sha256);
        transcript.absorb(label::PROFILE, b"merged-c1-pair-public-statement-kat");
        absorb_pool_v1_pair_public_statement_before_c1_root_v1(&mut transcript, bytes).unwrap();
        transcript.absorb(label::ROOT, &[0x51; 26]);
        let _lambda = transcript.challenge_qm31().unwrap();
        let _chi = transcript.challenge_qm31().unwrap();
        transcript.diagnostic_state()
    }

    #[test]
    fn pair_public_statement_layout_roundtrip_and_pre_root_transcript_kat() {
        let statement = late_statement();
        let mut encoded = [0u8; POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES];
        encode_pool_v1_pair_late_public_statement_v1(&statement, &mut encoded).unwrap();
        assert_eq!(&encoded[..8], b"ASPLATE1");
        assert_eq!(encoded[8], 1);
        assert_eq!(encoded[9], 2);
        assert_eq!(u16::from_le_bytes(encoded[10..12].try_into().unwrap()), 32);
        assert_eq!(u32::from_le_bytes(encoded[12..16].try_into().unwrap()), 800);
        assert_eq!(u32::from_le_bytes(encoded[16..20].try_into().unwrap()), 688);
        assert_eq!(
            u32::from_le_bytes(encoded[20..24].try_into().unwrap()),
            1_520
        );
        assert_eq!(&encoded[32..40], b"ASPLIVE1");
        assert_eq!(&encoded[832..836], b"ASJA");
        assert_eq!(
            decode_pool_v1_pair_late_public_statement_v1(&encoded),
            Ok(statement)
        );
        assert_eq!(
            merged_c1_transcript(&encoded),
            [
                0x79, 0x1c, 0x2c, 0x21, 0x1e, 0x9d, 0x84, 0x07, 0x39, 0x24, 0x95, 0xbc, 0xf1, 0x56,
                0xc3, 0xad, 0x4b, 0x73, 0x32, 0x84, 0x49, 0xd2, 0xbb, 0xbe, 0x2a, 0xb4, 0x37, 0x04,
                0xfc, 0x1b, 0x45, 0x66,
            ],
        );
    }

    #[test]
    fn late_public_statement_single_byte_mutations_are_rejected_or_rebound() {
        let mut encoded = [0u8; POOL_V1_PAIR_LATE_PUBLIC_STATEMENT_BYTES];
        encode_pool_v1_pair_late_public_statement_v1(&late_statement(), &mut encoded).unwrap();
        let baseline = merged_c1_transcript(&encoded);

        let mut header = encoded;
        header[0] ^= 1;
        assert_eq!(
            decode_pool_v1_pair_late_public_statement_v1(&header),
            Err(PoolV1PairLatePublicStatementErrorV1::WrongMagic)
        );

        let mut old_snapshot = encoded;
        old_snapshot[32 + 48] ^= 1;
        assert!(decode_pool_v1_pair_late_public_statement_v1(&old_snapshot).is_ok());
        assert_ne!(merged_c1_transcript(&old_snapshot), baseline);

        let mut afterstate = encoded;
        afterstate[832 + 16] ^= 1;
        assert!(decode_pool_v1_pair_late_public_statement_v1(&afterstate).is_ok());
        assert_ne!(merged_c1_transcript(&afterstate), baseline);

        let mut afterstate_envelope = encoded;
        afterstate_envelope[832] ^= 1;
        assert!(matches!(
            decode_pool_v1_pair_late_public_statement_v1(&afterstate_envelope),
            Err(PoolV1PairLatePublicStatementErrorV1::Afterstate(_))
        ));
    }
}

//! Production-inactive row/masking inventory for the eight-lane pair forest.
//!
//! The existing pair profile uses blocks `0..=53` for Poseidon, blocks
//! `54..=59` for 21 private path directions, and block `60` for value and
//! occupancy auxiliaries.  A literal use of blocks `61..=63` for the three
//! new parents is raw-opening-rank deficient.  The forest therefore permutes
//! the same ten-block tail: blocks `54..=56` are the three historical
//! lane-to-super-root parents, blocks `57..=62` carry all 24 private
//! directions, and block `63` carries value and occupancy auxiliaries.  Each
//! direction uses a subset of the frozen three-opening geometry: current/bit
//! at `r` and ordered children at `successor(r)`. Boolean gating binds the
//! selected child to the current digest; the other child is the sibling
//! witness itself, avoiding a redundant sibling copy. Four paths occupy local
//! base rows `1,5,9,13` in every auxiliary block.
//!
//! This is a layout gate only.  It does not activate a profile, change the
//! prover, or claim that the resulting mask map has full rank.  The prover
//! rank gate consumes this exact inventory separately.

use alloc::vec::Vec;

use crate::trace_v4::TraceCell;

use super::{
    pair_tree_hiding::{
        build_pool_v1_pair_copy_row_schedule_v1, pool_v1_pair_aux_cell_is_relation_used_v1,
        PoolV1PairCopyRowLinkKindV1, PoolV1PairCopyRowLinkV1, PoolV1PairHidingLayoutErrorV1,
        POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1,
    },
    pair_tree_profile::{
        POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK, POOL_V1_PAIR_TRACE_BLOCK_ROWS,
        POOL_V1_PAIR_TRACE_COLUMNS, POOL_V1_PAIR_TRACE_ROWS,
    },
};

pub const POOL_V1_PAIR_FOREST_LANES_V1: usize = 8;
pub const POOL_V1_PAIR_FOREST_SUPER_ROOT_DEPTH_V1: usize = 3;
pub const POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1: usize = 24;
pub const POOL_V1_PAIR_FOREST_FIRST_SUPER_ROOT_BLOCK_V1: usize = 54;
pub const POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1: usize = 57;
pub const POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1: usize = 57 * 16;
pub const POOL_V1_PAIR_FOREST_PATH_AUX_ROW_END_V1: usize = 63 * 16;
pub const POOL_V1_PAIR_FOREST_VALUE_AUX_ROW_START_V1: usize = 63 * 16;
pub const POOL_V1_PAIR_FOREST_INPUT_OCCUPANCY_AUX_ROW_V1: usize = 63 * 16 + 9;
pub const POOL_V1_PAIR_FOREST_OUTPUT_OCCUPANCY_AUX_ROW_V1: usize = 63 * 16 + 10;
pub const POOL_V1_PAIR_FOREST_SEMANTIC_ROW_END_V1: usize = 64 * 16;
pub const POOL_V1_PAIR_FOREST_COPY_ROW_LINKS_V1: usize = 136;
pub const POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_V1: usize = 214;
pub const POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_CELLS_V1: usize = 3_803;
pub const PINNED_POOL_V1_PAIR_FOREST_COPY_ROW_SCHEDULE_FINGERPRINT_V1: u64 = 0x4808_09b8_3677_8dc6;
pub const PINNED_POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_FINGERPRINT_V1: u64 = 0xdf39_4a5a_8554_d09c;
pub const PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1: u64 = 0xf9da_f3d5_4f42_85d1;

const POOL_V1_PAIR_FOREST_PATH_BASE_LOCAL_ROWS_V1: [[usize; 4]; 6] = [
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
];

#[inline]
pub const fn pool_v1_pair_forest_path_base_row_v1(level: usize) -> Option<usize> {
    if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        return None;
    }
    Some(
        POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1
            + (level / POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK) * POOL_V1_PAIR_TRACE_BLOCK_ROWS
            + POOL_V1_PAIR_FOREST_PATH_BASE_LOCAL_ROWS_V1
                [level / POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK]
                [level % POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK],
    )
}

#[inline]
pub const fn pool_v1_pair_forest_membership_hash_block_v1(level: usize) -> Option<usize> {
    if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        None
    } else if level <= 20 {
        Some(4 + level)
    } else {
        Some(33 + level)
    }
}

#[inline]
fn link(
    kind: PoolV1PairCopyRowLinkKindV1,
    producer_row: usize,
    consumer_row: usize,
) -> PoolV1PairCopyRowLinkV1 {
    PoolV1PairCopyRowLinkV1 {
        kind,
        producer_row: producer_row as u16,
        consumer_row: consumer_row as u16,
    }
}

fn endpoint_counts(
    links: &[PoolV1PairCopyRowLinkV1],
) -> Result<([u8; 1024], [u8; 1024]), PoolV1PairHidingLayoutErrorV1> {
    let mut producers = [0u8; 1024];
    let mut consumers = [0u8; 1024];
    for link in links {
        for (row, counts) in [
            (usize::from(link.producer_row), &mut producers),
            (usize::from(link.consumer_row), &mut consumers),
        ] {
            if row >= POOL_V1_PAIR_TRACE_ROWS || counts[row] >= 2 {
                return Err(PoolV1PairHidingLayoutErrorV1::EndpointCapacity { row: row as u16 });
            }
            counts[row] += 1;
        }
    }
    Ok((producers, consumers))
}

pub fn build_pool_v1_pair_forest_copy_row_schedule_v1(
) -> Result<Vec<PoolV1PairCopyRowLinkV1>, PoolV1PairHidingLayoutErrorV1> {
    let mut links = build_pool_v1_pair_copy_row_schedule_v1()?
        .into_iter()
        .filter(|scheduled| {
            !matches!(
                scheduled.kind,
                PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { .. }
                    | PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { .. }
                    | PoolV1PairCopyRowLinkKindV1::PrivatePathRight { .. }
            )
        })
        .collect::<Vec<_>>();
    // The existing schedule's auxiliary endpoints live in rows 864..975.
    // Move that complete seven-block region forward by three blocks while
    // leaving every existing Poseidon endpoint unchanged.
    for scheduled in &mut links {
        if usize::from(scheduled.producer_row) >= 54 * POOL_V1_PAIR_TRACE_BLOCK_ROWS {
            scheduled.producer_row += 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS as u16;
        }
        if usize::from(scheduled.consumer_row) >= 54 * POOL_V1_PAIR_TRACE_BLOCK_ROWS {
            scheduled.consumer_row += 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS as u16;
        }
    }
    links.reserve(3 * POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1);
    for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        let auxiliary = pool_v1_pair_forest_path_base_row_v1(level)
            .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
        let target_block = pool_v1_pair_forest_membership_hash_block_v1(level)
            .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
        let previous_block = if level == 0 {
            3
        } else {
            pool_v1_pair_forest_membership_hash_block_v1(level - 1)
                .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?
        };
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level: level as u8 },
            previous_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS + 11,
            auxiliary,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level: level as u8 },
            auxiliary + 1,
            target_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS + 12,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level: level as u8 },
            auxiliary + 1,
            target_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS,
        ));
    }
    if links.len() != POOL_V1_PAIR_FOREST_COPY_ROW_LINKS_V1 {
        return Err(PoolV1PairHidingLayoutErrorV1::Shape);
    }
    endpoint_counts(&links)?;
    Ok(links)
}

pub fn pool_v1_pair_forest_copy_active_rows_v1() -> Result<Vec<u16>, PoolV1PairHidingLayoutErrorV1>
{
    let mut rows = build_pool_v1_pair_forest_copy_row_schedule_v1()?
        .into_iter()
        .flat_map(|link| [link.producer_row, link.consumer_row])
        .collect::<Vec<_>>();
    rows.sort_unstable();
    rows.dedup();
    Ok(rows)
}

pub fn pool_v1_pair_forest_copy_active_row_masks_v1(
) -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1> {
    let mut masks = [0u16; 64];
    for row in pool_v1_pair_forest_copy_active_rows_v1()? {
        masks[usize::from(row) >> 4] |= 1 << (usize::from(row) & 15);
    }
    Ok(masks)
}

pub fn pool_v1_pair_forest_copy_inactive_row_masks_v1(
) -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1> {
    Ok(pool_v1_pair_forest_copy_active_row_masks_v1()?.map(|mask| !mask))
}

fn forest_path_aux_cell_is_used(row: usize, column: usize) -> bool {
    for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        let Some(base) = pool_v1_pair_forest_path_base_row_v1(level) else {
            return false;
        };
        if (row == base && column <= 8) || row == base + 1 {
            return true;
        }
    }
    false
}

#[inline]
fn forest_poseidon_row(row: usize) -> bool {
    row < POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1 * POOL_V1_PAIR_TRACE_BLOCK_ROWS
}

fn forest_aux_cell_is_used(row: usize, column: usize) -> bool {
    if row < POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1 {
        return false;
    }
    if row < POOL_V1_PAIR_FOREST_VALUE_AUX_ROW_START_V1 {
        forest_path_aux_cell_is_used(row, column)
    } else {
        let translated = row - 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS;
        pool_v1_pair_aux_cell_is_relation_used_v1(translated, column)
    }
}

pub fn pool_v1_pair_forest_relation_free_mask_cells_v1(
) -> Result<Vec<TraceCell>, PoolV1PairHidingLayoutErrorV1> {
    let _ = build_pool_v1_pair_forest_copy_row_schedule_v1()?;
    let mut cells = Vec::new();
    for column in 0..POOL_V1_PAIR_TRACE_COLUMNS {
        for row in 0..POOL_V1_PAIR_TRACE_ROWS {
            let poseidon = forest_poseidon_row(row);
            let padding = poseidon
                && row % POOL_V1_PAIR_TRACE_BLOCK_ROWS
                    >= POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1;
            let auxiliary = !poseidon && !forest_aux_cell_is_used(row, column);
            if padding || auxiliary {
                cells.push(TraceCell {
                    row: row as u16,
                    column: column as u8,
                });
            }
        }
    }
    Ok(cells)
}

fn fingerprint_bytes<'a>(bytes: impl IntoIterator<Item = &'a u8>) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn copy_kind_code(kind: PoolV1PairCopyRowLinkKindV1) -> [u8; 3] {
    match kind {
        PoolV1PairCopyRowLinkKindV1::SpongeCarry { from, to } => [0, from, to],
        PoolV1PairCopyRowLinkKindV1::OwnerOutput => [1, 0, 0],
        PoolV1PairCopyRowLinkKindV1::NullifierKey => [2, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltHead => [3, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltTail => [4, 0, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level } => [5, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level } => [6, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level } => [7, level, 0],
        PoolV1PairCopyRowLinkKindV1::ValueSource { value } => [8, value, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationInput => [9, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationRecipient => [10, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationChange => [11, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationPartial => [12, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSecondCommitment => [13, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSelectedSide => [14, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputSecondCommitment => [15, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirst => [16, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirstWithdrawal => [17, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairSecond => [18, 0, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentLeft { level } => [19, level, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentRight { level } => [20, level, 0],
    }
}

pub fn pool_v1_pair_forest_copy_row_schedule_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = build_pool_v1_pair_forest_copy_row_schedule_v1()?
        .into_iter()
        .flat_map(|link| {
            let kind = copy_kind_code(link.kind);
            let producer = link.producer_row.to_le_bytes();
            let consumer = link.consumer_row.to_le_bytes();
            [
                kind[0],
                kind[1],
                kind[2],
                producer[0],
                producer[1],
                consumer[0],
                consumer[1],
            ]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_forest_copy_active_rows_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = pool_v1_pair_forest_copy_active_rows_v1()?
        .into_iter()
        .flat_map(u16::to_le_bytes)
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_forest_relation_free_mask_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = pool_v1_pair_forest_relation_free_mask_cells_v1()?
        .into_iter()
        .flat_map(|cell| {
            let row = cell.row.to_le_bytes();
            [row[0], row[1], cell.column]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

const _: () = assert!(POOL_V1_PAIR_FOREST_LANES_V1 == 1 << 3);
const _: () = assert!(POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 == 6 * 4);
const _: () = assert!(POOL_V1_PAIR_FOREST_FIRST_SUPER_ROOT_BLOCK_V1 * 16 == 864);
const _: () = assert!(POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1 == 54 + 3);
const _: () = assert!(POOL_V1_PAIR_FOREST_SEMANTIC_ROW_END_V1 == POOL_V1_PAIR_TRACE_ROWS);

#[cfg(test)]
mod tests {
    use super::*;
    use std::println;

    fn contains(cells: &[TraceCell], row: usize, column: usize) -> bool {
        cells
            .binary_search_by_key(&(column as u8, row as u16), |cell| (cell.column, cell.row))
            .is_ok()
    }

    #[test]
    fn every_private_path_uses_distinct_frozen_z_and_successor_rows() {
        let mut occupied = [false; POOL_V1_PAIR_TRACE_ROWS];
        for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
            let base = pool_v1_pair_forest_path_base_row_v1(level).unwrap();
            for row in [base, base + 1] {
                assert_eq!(base >> 4, row >> 4);
                assert!(!occupied[row], "path row collision at {row}");
                occupied[row] = true;
            }
        }
    }

    #[test]
    fn exact_forest_layout_inventory() {
        let schedule = build_pool_v1_pair_forest_copy_row_schedule_v1().unwrap();
        let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
        let masks = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
        assert_eq!(schedule.len(), 136);
        assert_eq!(active.len(), POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_V1);
        assert_eq!(masks.len(), POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_CELLS_V1);
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(21), Some(997));
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(22), Some(1001));
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(23), Some(1005));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(21), Some(54));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(22), Some(55));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(23), Some(56));
        assert!(!contains(&masks, 864, 0));
        assert!(!contains(&masks, 876, 0));
        assert!(contains(&masks, 877, 0));
        assert!(!contains(&masks, 997, 0));
        assert_eq!(
            pool_v1_pair_forest_copy_row_schedule_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_COPY_ROW_SCHEDULE_FINGERPRINT_V1
        );
        assert_eq!(
            pool_v1_pair_forest_copy_active_rows_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_FINGERPRINT_V1
        );
        assert_eq!(
            pool_v1_pair_forest_relation_free_mask_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1
        );
        println!(
            "forest links={} active={} masks={} copy_fp={:#018x} active_fp={:#018x} mask_fp={:#018x}",
            schedule.len(),
            active.len(),
            masks.len(),
            pool_v1_pair_forest_copy_row_schedule_fingerprint_v1().unwrap(),
            pool_v1_pair_forest_copy_active_rows_fingerprint_v1().unwrap(),
            pool_v1_pair_forest_relation_free_mask_fingerprint_v1().unwrap(),
        );
    }
}

