#[derive(Clone, Copy)]
pub struct Schedule {
    pub data: [PoolV1PairCopyRowLinkV1; 136],
    pub len: usize,
}
impl Schedule {
    fn new() -> Self {
        Self {
            data: [PoolV1PairCopyRowLinkV1 {
                kind: PoolV1PairCopyRowLinkKindV1::OwnerOutput,
                producer_row: 0,
                consumer_row: 0,
            }; 136],
            len: 0,
        }
    }
    fn push(&mut self, value: PoolV1PairCopyRowLinkV1) {
        self.data[self.len] = value;
        self.len += 1;
    }
    fn len(&self) -> usize {
        self.len
    }
}
